using System;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "EtherealPlumeOmenData", menuName = "Data/Battle/Omens System/Omen Data/Sothis/EtherealPlumeOmenData")]
public class EtherealPlumeOmenData : OmenData
{
	protected Action omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate
		{
			omenInstance.EnqueueOmenFeedbackAndPlay();
		};
		ReferenceSingleton<SothisOmensHandler>.Instance.EtherealPlumeOmenAction = omenAction;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<SothisOmensHandler>.Instance.EtherealPlumeOmenAction = null;
	}
}
